import { GameState, Hero, Position, MapTile } from '../types/game';
import { gameService } from './api';

// Valida movimiento consultando al backend
export const canMoveToPosition = async (gameId: string, heroId: string, target: Position): Promise<boolean> => {
  try {
    const response = await gameService.validateMove(gameId, heroId, target);
    return response.data.valid;
  } catch (error) {
    console.error('Error validating move:', error);
    return false;
  }
};

// Calcula el camino a través del backend
export const calculatePath = async (gameId: string, heroId: string, target: Position): Promise<Position[]> => {
  try {
    const response = await gameService.calculatePath(gameId, heroId, target);
    return response.data.path;
  } catch (error) {
    console.error('Error calculating path:', error);
    return [];
  }
};

// Ejecuta el movimiento a través del backend
export const executeMove = async (gameId: string, heroId: string, target: Position): Promise<GameState> => {
  try {
    const response = await gameService.moveHero(gameId, heroId, target);
    return response.data;
  } catch (error) {
    console.error('Error executing move:', error);
    throw error;
  }
};

// Finaliza el turno a través del backend
export const endTurn = async (gameId: string): Promise<GameState> => {
  try {
    const response = await gameService.endTurn(gameId);
    return response.data;
  } catch (error) {
    console.error('Error ending turn:', error);
    throw error;
  }
};
